def fizz_buzz(n: int):
    def count_sevens(num):
        return str(num).count('7')

    def is_divisible(num):
        return num % 11 == 0 or num % 13 == 0

    count = 0
    for i in range(1, n):
        if is_divisible(i):
            count += count_sevens(i)

    return count

